theorem IsCoupling.map_swap {alpha : Type u} {beta : Type v}
    {joint : PMF (alpha × beta)} {p : PMF alpha} {q : PMF beta}
    (h : IsCoupling joint p q) : IsCoupling (joint.map Prod.swap) q p

theorem isCoupling_channelJoint_const {alpha : Type u} {beta : Type v}
    (p : PMF alpha) (q : PMF beta) :
    IsCoupling (channelJoint p (fun _ => q)) p q

theorem map_apply_eq_zero_of_notMem_range {alpha : Type u} {beta : Type*}
    (p : PMF alpha) {f : alpha -> beta} {b : beta} (hb : b ∉ Set.range f) :
    p.map f b = 0

theorem map_apply_equiv {alpha : Type u} {beta : Type*}
    (p : PMF alpha) (e : alpha ≃ beta) (a : alpha) :
    p.map e (e a) = p a

theorem map_apply_of_injective {alpha : Type u} {beta : Type*}
    (p : PMF alpha) {f : alpha -> beta} (hf : Function.Injective f) (a : alpha) :
    p.map f (f a) = p a

theorem bind_channelComp {alpha : Type u} {beta : Type v} {gamma : Type w}
    (p : PMF alpha) (W : alpha -> PMF beta) (V : beta -> PMF gamma) :
    p.bind (channelComp W V) = (p.bind W).bind V

theorem channelComp_apply {alpha : Type u} {beta : Type v} {gamma : Type w}
    (W : alpha -> PMF beta) (V : beta -> PMF gamma) (a : alpha) (c : gamma) :
    channelComp W V a c = ∑' b, W a b * V b c

theorem entropyOf_comp_injective
    {omega : Type u} {alpha : Type v} {beta : Type w}
    [Fintype alpha] [Fintype beta]
    (p : PMF omega) (X : omega -> alpha) {f : alpha -> beta}
    (hf : Function.Injective f) :
    entropyOf p (fun omega => f (X omega)) = entropyOf p X

theorem entropy_map_equiv {alpha : Type u} {beta : Type v}
    [Fintype alpha] [Fintype beta] (p : PMF alpha) (e : alpha ≃ beta) :
    entropy (p.map e) = entropy p

theorem entropy_map_swap {alpha : Type u} {beta : Type v}
    [Fintype alpha] [Fintype beta] (p : PMF (alpha × beta)) :
    entropy (p.map Prod.swap) = entropy p

theorem jointEntropy_map_swap {alpha : Type u} {beta : Type v}
    [Fintype alpha] [Fintype beta] (p : PMF (alpha × beta)) :
    jointEntropy (p.map Prod.swap) = jointEntropy p

theorem apply_eq_zero_of_fstMarginal_eq_zero {alpha : Type u} {beta : Type v}
    [Finite beta] (p : PMF (alpha × beta)) {a : alpha}
    (h : fstMarginal p a = 0) (b : beta) :
    p (a, b) = 0

theorem apply_eq_zero_of_sndMarginal_eq_zero {alpha : Type u} {beta : Type v}
    [Finite alpha] (p : PMF (alpha × beta)) (a : alpha) {b : beta}
    (h : sndMarginal p b = 0) :
    p (a, b) = 0

theorem fstMarginal_ne_zero_of_apply_ne_zero {alpha : Type u} {beta : Type v}
    [Finite beta] (p : PMF (alpha × beta)) {a : alpha} {b : beta}
    (h : p (a, b) ≠ 0) :
    fstMarginal p a ≠ 0

theorem sndMarginal_ne_zero_of_apply_ne_zero {alpha : Type u} {beta : Type v}
    [Finite alpha] (p : PMF (alpha × beta)) {a : alpha} {b : beta}
    (h : p (a, b) ≠ 0) :
    sndMarginal p b ≠ 0

theorem sum_logSumTerm_ne_bot {ι : Type u}
    (s : Finset ι) (a b : ι → NNReal) :
    (∑ i ∈ s, logSumTerm (a i) (b i)) ≠ ⊥

@[simp]
theorem support_condFstGivenSnd {alpha : Type u} {beta : Type v}
    [Fintype alpha] (p : PMF (alpha × beta)) (b : beta)
    (hb : sndMarginal p b ≠ 0) :
    (condFstGivenSnd p b hb).support = {a | p (a, b) ≠ 0}

theorem selfInfo_of_toReal_ne_zero {alpha : Type u} (p : PMF alpha) {a : alpha}
    (ha : (p a).toReal ≠ 0) :
    selfInfo p a = -Real.log (p a).toReal

theorem familyEntropy_le_sum_singletons
    {Var : Type u} {alpha : Var -> Type v}
    [DecidableEq Var] [forall i, Fintype (alpha i)]
    (q : PMF ((i : Var) -> alpha i)) (s : Finset Var) :
    familyEntropy q s ≤ ∑ i ∈ s, familyEntropy q {i}

theorem familyEntropy_mono
    {Var : Type u} {alpha : Var -> Type v}
    [DecidableEq Var] [forall i, Fintype (alpha i)]
    (q : PMF ((i : Var) -> alpha i)) {s t : Finset Var}
    (hst : s ⊆ t) :
    familyEntropy q s ≤ familyEntropy q t

theorem familyEntropy_subadditivity_of_nodup
    {Var : Type u} {alpha : Var -> Type v}
    [DecidableEq Var] [forall i, Fintype (alpha i)]
    (q : PMF ((i : Var) -> alpha i)) (l : List Var) (hl : l.Nodup) :
    familyEntropy q l.toFinset ≤
      ∑ k : Fin l.length, familyEntropy q {l.get k}

theorem isMutuallyIndependentFamily_mono
    {Var : Type u} {alpha : Var -> Type v}
    [forall i, Finite (alpha i)]
    (q : PMF ((i : Var) -> alpha i)) {s t : Finset Var}
    (h : IsMutuallyIndependentFamily q t) (hst : s ⊆ t) :
    IsMutuallyIndependentFamily q s

@[simp] theorem isMutuallyIndependentFamily_singleton
    {Var : Type u} {alpha : Var -> Type v}
    (q : PMF ((i : Var) -> alpha i)) (i : Var) :
    IsMutuallyIndependentFamily q {i}

theorem indepProd_map_swap {alpha : Type u} {beta : Type v}
    (p : PMF alpha) (q : PMF beta) :
    (indepProd p q).map Prod.swap = indepProd q p

theorem condEntropyFstGivenSnd_eq_zero_iff_of_sndMarginal_ne_zero
    {alpha : Type u} {beta : Type v}
    [Fintype alpha] (p : PMF (alpha × beta)) {b : beta}
    (hb : sndMarginal p b ≠ 0) :
    condEntropyFstGivenSnd p b = 0 ↔
      ∃ a, condFstGivenSnd p b hb = PMF.pure a

theorem condEntropy_nonneg {alpha : Type u} {beta : Type v}
    [Fintype alpha] [Fintype beta] (p : PMF (alpha × beta)) :
    0 <= condEntropy p

theorem mutualInfo_nonneg {alpha : Type u} {beta : Type v}
    [Fintype alpha] [Fintype beta] (p : PMF (alpha × beta)) :
    0 <= mutualInfo p
